from .exceptions import DegeneratedEntry


class Fault:
    """ Class representing Fault entry from fault_history_log.txt """

    def __init__(self, entry):
        self._entry = [str(entry_value).strip() for entry_value in entry.split("\t")]

        try:
            self.timestamp = self._entry[0]
            self.id = self._entry[1]
            self.source = self._entry[2]
            self.severity = self._entry[3]
            self.num_of_faults = self._entry[4:]

        except IndexError:
            raise DegeneratedEntry("Could not read Entry as some information is missing! "
                                   "\n Raw entry: {0}"
                                   "\n Parsed entry: {1}".format(entry, self._entry))
